                op, 
                float(a) if a is not None else None, 
                float(b) if b is not None else None, 
                result
            ))

    def add(self, a: Numeric, b: Numeric) -> float:
        """Calculate the sum of a and b."""
        self._validate(a, b)
        res = float(a + b)
        self._record("add", a, b, res)
